  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  grain: {
    type: "boolean",
    default: true,
    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","value","label","next","hold","stagger","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  value: "150",
  label: "updates in this release",
  next: "Here’s everything new.",
  hold: 56,
  stagger: 3,
  accent: "#3B5BFD",
  fontFamily: "Sora",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type PlusOpenElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PlusOpenBase>;

const PlusOpenInner = forwardRef<
  HTMLDivElement,
  PlusOpenElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PlusOpen>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PlusOpenBase
          {...(componentProps as unknown as ComponentProps<typeof PlusOpenBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PlusOpen = Interactive.withSchema({
  Component: PlusOpenInner,
  componentName: "<PlusOpen>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
